"use client"

import * as React from "react"
import { Spinner } from "@/components/ui/spinner"
import { useFlowPress } from "@/lib/sahajiv-motion/flow-press"
import { useMorph } from "@/lib/sahajiv-motion/use-morph"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "v-btn [display:inline-flex] items-center justify-center gap-[var(--s-2)] h-[var(--ctl-md)] px-[var(--s-5)] py-0 rounded-[var(--r-pill)] text-[length:var(--fs-control)] font-[number:var(--fw-control)] leading-none whitespace-nowrap bg-[var(--primary)] text-[color:var(--primary-foreground)] motion-safe:active:[transform:translateY(1px)]",
  {
    variants: {
      variant: {
        default: "",
        accent: "-accent bg-[var(--v-pink)] text-[color:var(--v-on-accent)] hover:bg-[var(--v-pink-deep)]",
        secondary: "-secondary bg-[var(--v-beige)] text-[color:var(--v-text)] [box-shadow:inset_0_0_0_1px_var(--v-text-2)] hover:[box-shadow:inset_0_0_0_1px_var(--v-text)]",
        ghost: "-ghost bg-transparent text-[color:var(--v-text)] hover:bg-[var(--v-beige)]",
        outline: "-outline bg-transparent text-[color:var(--v-text)] [box-shadow:inset_0_0_0_1px_var(--v-border)] hover:bg-[var(--v-beige-2)]",
        danger: "-danger bg-[var(--v-danger-fill)] text-[color:var(--destructive-foreground)]",
        block: "-block w-full",
      },
      size: {
        default: "",
        sm: "-sm h-[var(--ctl-sm)] px-[var(--s-4)] text-[13px]",
        lg: "-lg h-[var(--ctl-lg)] px-[var(--s-6)] text-[length:var(--fs-body)]",
      },
      fullWidth: { true: "-block w-full", false: "" },
    },
    defaultVariants: { variant: "default", size: "default", fullWidth: false },
  },
)

type ButtonProps = React.ComponentProps<"button"> & VariantProps<typeof buttonVariants> & {
  loading?: boolean
  loadingIndicator?: React.ReactNode
}

function Button({ ref: externalRef, className, variant, size, fullWidth, loading, loadingIndicator, children, type = "button", "aria-busy": ariaBusy, ...props }: ButtonProps) {
  const morphRef = useMorph<HTMLButtonElement>("buttons", externalRef)
  const pressRef = useFlowPress(morphRef)
  const busy = loading ?? (ariaBusy === true || ariaBusy === "true")
  return (
    <button ref={pressRef} data-slot="button" data-part="root" data-state={props.disabled ? "disabled" : busy ? "busy" : "rest"} type={type} aria-busy={busy || undefined} className={cn(buttonVariants({ variant, size, fullWidth }), "leading-none", className)} {...props}>
      {busy && (loadingIndicator ?? <ButtonIndicator />)}
      {children}
    </button>
  )
}

function ButtonIndicator({className,...props}:React.ComponentProps<"span">) {
  return <Spinner data-slot="button-indicator" data-part="indicator" data-label="" aria-hidden="true" className={className} {...props}/>
}

export { Button, ButtonIndicator, buttonVariants }
export type { ButtonProps }

@layer sahajiv-states {
/* Mixed transitions and final state precedence from the authored cascade. */
.v-btn:where([data-slot]) {
  transition: background var(--t-micro) var(--enter), transform var(--t-micro) var(--enter), opacity var(--t-micro);
}
.v-btn:where([data-slot]):not(.-accent):not(.-secondary):not(.-ghost):not(.-outline):not(.-danger):hover {
  background: color-mix(in oklab, var(--primary) 88%, var(--v-canvas));
}
.v-btn:where([data-slot]).-secondary:hover { background: color-mix(in oklab, var(--v-beige) 92%, var(--v-ink)); }
.v-btn:where([data-slot]).-danger:hover { background: color-mix(in oklab, var(--v-danger-fill) 88%, black); }
:root[data-mode="dark"] .v-btn:where([data-slot]):not(.-accent):not(.-secondary):not(.-ghost):not(.-outline):not(.-danger) {
  background: var(--v-pink); color: var(--v-on-accent);
}
.v-btn:where([data-slot]):is(:disabled, [aria-disabled="true"]) {
  background: var(--v-disabled-face); color: var(--v-disabled-ink);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge); cursor: not-allowed; transform: none;
}
:root[data-mode="dark"] .v-btn:where([data-slot]):is(.-secondary,.-ghost,.-outline) { color: var(--v-text); }
.v-btn:where([data-slot]) .v-icon { width: 18px; height: 18px; }
.v-btn:where([data-slot])[aria-busy="true"] {
  position: relative; overflow: hidden; cursor: progress; pointer-events: none; gap: 10px;
}
.v-btn:where([data-slot])[aria-busy="true"] .v-pulse { display: inline-grid; place-items: center; position: relative; width: 20px; height: 20px; }
.v-btn:where([data-slot])[aria-busy="true"] .v-pulse svg { width: 100%; height: 100%; overflow: visible; }
.v-btn:where([data-slot])[aria-busy="true"] .v-pulse .seed { fill: var(--v-pink); }
.v-btn:where([data-slot]):is(.-secondary,.-ghost,.-outline)[aria-busy="true"] .v-pulse .seed { fill: var(--v-brand); }
.v-btn:where([data-slot])[aria-busy="true"] .v-pulse .core { fill: var(--v-canvas); }
.v-btn:where([data-slot]):is(.-secondary,.-ghost,.-outline)[aria-busy="true"] .v-pulse .core,
:root[data-mode="dark"] .v-btn:where([data-slot])[aria-busy="true"] .v-pulse .core { fill: var(--v-on-accent); }
.v-btn:where([data-slot])[aria-busy="true"]::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(100deg, transparent 20%, rgba(251,244,230,.14) 50%, transparent 80%);
  transform: translateX(-100%); animation: v-button-sweep 2.2s cubic-bezier(.4,0,.2,1) infinite; pointer-events: none;
}
.v-btn:where([data-slot]):is(.-secondary,.-ghost,.-outline)[aria-busy="true"]::after {
  background: linear-gradient(100deg, transparent 20%, rgba(17,17,17,.06) 50%, transparent 80%);
}
.v-btn:where([data-slot])[aria-busy="true"] > :not(.v-pulse) { position: relative; z-index: 1; opacity: .85; }
@keyframes v-button-sweep { to { transform: translateX(100%); } }
@media (prefers-reduced-motion: reduce) {
  .v-btn:where([data-slot])[aria-busy="true"]::after { animation: none; display: none; }
}

}
